#:sdk Microsoft.NET.Sdk.Web #:package Yarp.ReverseProxy@2.0.0 #:package System.Threading.Channels@8.0.0 #:property LangVersion=preview #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable #:property PublishAot=true  [SkipLocalsInit] public sealed class BatchMiddleware {     private readonly Channel<ProxyRequest> _requestChannel;     private readonly BatchOptions _options;     private readonly CancellationTokenSource _cts;      public BatchMiddleware(IOptions<BatchOptions> options)     {         _options = options.Value;         _cts = new CancellationTokenSource();                  _requestChannel = Channel.CreateBounded<ProxyRequest>(             new BoundedChannelOptions(_options.BatchSize * 2)             {                 SingleReader = true,                 AllowSynchronousContinuations = true,                 FullMode = BoundedChannelFullMode.Wait             });                      _ = Task.Run(ProcessBatchesAsync);     }      [MethodImpl(MethodImplOptions.AggressiveOptimization)]     private async Task ProcessBatchesAsync()     {         var batch = new List<ProxyRequest>(_options.BatchSize);                  while (!_cts.IsCancellationRequested)         {             while (batch.Count < _options.BatchSize &&                     _requestChannel.Reader.TryRead(out var request))             {                 batch.Add(request);             }                          if (batch.Count > 0)             {                 await ProcessBatchAsync(batch);                 batch.Clear();             }             else             {                 await Task.Delay(_options.BatchTimeout, _cts.Token);             }         }     }      [MethodImpl(MethodImplOptions.AggressiveOptimization)]     private async Task ProcessBatchAsync(IReadOnlyList<ProxyRequest> batch)     {         // 实现批量请求处理逻辑         // ... 实际批处理逻辑实现     } }  public class BatchOptions {     public int BatchSize { get; set; } = 100;     public TimeSpan BatchTimeout { get; set; } = TimeSpan.FromMilliseconds(50); }
